// Получаем данные из запроса
const query = $input.item.json.query || '';
const city = $input.item.json.city || 'Благовещенск';
const region = $input.item.json.region || 'Амурская область';

if (!query) {
  return {
    json: {
      error: true,
      message: 'Запрос обязателен'
    }
  };
}

// Формируем поисковый запрос
const searchQuery = `Найди 10 сайтов компаний: ${query} в городе ${city}, ${region}. Верни список URL сайтов компаний в формате JSON массива: [{"url": "https://site1.ru", "name": "Название компании", "description": "краткое описание"}, ...]. Не включай социальные сети (vk.com, instagram.com и т.д.), маркетплейсы (avito, 2gis), справочники. Только официальные сайты компаний.`;

return {
  json: {
    search_query: searchQuery,
    original_query: query,
    city: city,
    region: region
  }
};

