// Парсинг ответа от Perplexity AI
const response = $input.item.json;
const results = [];

try {
  // Получаем ответ от AI
  let aiContent = response.choices?.[0]?.message?.content || '[]';

  // Удаляем markdown блоки если есть
  aiContent = aiContent.replace(/```json\n?/g, '').replace(/```/g, '').trim();

  // Парсим JSON
  let companies = [];
  try {
    companies = JSON.parse(aiContent);
  } catch (parseError) {
    console.error('Parse error:', parseError.message);
    console.log('AI Content:', aiContent);

    // Пытаемся найти JSON массив в тексте
    const jsonMatch = aiContent.match(/\[\{[^\]]+\}\]/);
    if (jsonMatch) {
      companies = JSON.parse(jsonMatch[0]);
    }
  }

  // Проверяем что получили массив
  if (!Array.isArray(companies)) {
    companies = [];
  }

  // Обрабатываем каждую компанию
  for (const company of companies) {
    let url = company.url || '';

    // Пропускаем невалидные URL
    if (!url) continue;

    // Добавляем https:// если отсутствует
    if (!url.match(/^https?:\/\//i)) {
      url = 'https://' + url;
    }

    // Фильтруем нерелевантные домены
    const excludeDomains = [
      'vk.com', 'facebook.com', 'instagram.com', 'youtube.com',
      'avito.ru', '2gis.ru', 'yandex.ru', 'google.com',
      'wikipedia.org', 'zoon.ru', 'flamp.ru', 'yell.ru'
    ];

    try {
      const hostname = new URL(url).hostname.replace('www.', '');
      if (excludeDomains.some(d => hostname.includes(d))) {
        continue;
      }

      results.push({
        json: {
          url: url,
          company_name: company.name || 'Unknown',
          description: company.description || '',
          source: 'perplexity_ai',
          created_at: new Date().toISOString(),
          status: 0
        }
      });
    } catch (e) {
      console.error('URL parse error:', e.message);
      continue;
    }
  }

} catch (error) {
  console.error('Error processing Perplexity response:', error.message);
}

if (results.length === 0) {
  return [{
    json: {
      no_results: true,
      message: 'Компании не найдены'
    }
  }];
}

return results;
